library(dplyr)
library(readr)
library(labelled)
library(tidyr)
library(purrr)

# Load all files
w1 <- read_delim("data/input/wave_one_lsype_young_person_2020.tab", delim = "\t", show_col_types = FALSE)
w4 <- read_delim("data/input/wave_four_lsype_young_person_2020.tab", delim = "\t", show_col_types = FALSE)
w5 <- read_delim("data/input/wave_five_lsype_young_person_2020.tab", delim = "\t", show_col_types = FALSE)
w6 <- read_delim("data/input/wave_six_lsype_young_person_2020.tab", delim = "\t", show_col_types = FALSE)
w7 <- read_delim("data/input/wave_seven_lsype_young_person_2020.tab", delim = "\t", show_col_types = FALSE)
w8 <- read_delim("data/input/ns8_2015_derived.tab", delim = "\t", show_col_types = FALSE)
w9 <- read_delim("data/input/ns9_2022_derived_variables.tab", delim = "\t", show_col_types = FALSE)

# Merge all datasets
merged <- w1 %>%
  full_join(w4, by = "NSID") %>%
  full_join(w5, by = "NSID") %>%
  full_join(w6, by = "NSID") %>%
  full_join(w7, by = "NSID") %>%
  full_join(w8, by = "NSID") %>%
  full_join(w9, by = "NSID")

cat("Merged data dimensions:", dim(merged), "\n")

# Helper function to convert NAs to standard missing codes
convert_missing <- function(x, ref_var) {
  # Map user missing codes from ref_var to standard codes
  ref_vals <- attr(ref_var, "labels")
  if (is.null(ref_vals)) return(x)

  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      # Find corresponding ref value and get its label
      ref_code <- ref_var[i]
      if (!is.na(ref_code)) {
        lbl <- as.character(ref_vals[as.character(ref_code)])
        if (!is.na(lbl)) {
          if (grepl("Refused", lbl, ignore.case = TRUE)) x[i] <- -9
          else if (grepl("Insufficient|Unable to classify", lbl, ignore.case = TRUE)) x[i] <- -8
          else if (grepl("Not asked|Not applicable|still at school", lbl, ignore.case = TRUE)) x[i] <- -1
          else if (grepl("Missing household|information lost", lbl, ignore.case = TRUE)) x[i] <- -2
          else x[i] <- -3
        } else {
          x[i] <- -3
        }
      } else {
        x[i] <- -3
      }
    }
  }
  x
}

# Recode function for 6-category collapsed ecoact
collapse_economic <- function(x, source_var) {
  # First convert missing values
  x <- convert_missing(x, source_var)

  # Source value labels for this variable
  src_labels <- attr(source_var, "labels")

  # Map values to 6 categories
  result <- x
  for (i in seq_along(x)) {
    if (is.na(x[i]) || x[i] < 0) {
      # Already handled by convert_missing, keep as is
      next
    }

    val <- x[i]
    # Check if this value is a user-missing code in source
    if (!is.null(src_labels) && as.character(val) %in% names(src_labels)) {
      lbl <- as.character(src_labels[as.character(val)])
      if (grepl("Refused", lbl, ignore.case = TRUE)) {
        result[i] <- -9
      } else if (grepl("Insufficient|Unable to classify", lbl, ignore.case = TRUE)) {
        result[i] <- -8
      } else if (grepl("Not asked|Not applicable|still at school", lbl, ignore.case = TRUE)) {
        result[i] <- -3
      } else if (grepl("Missing household|information lost", lbl, ignore.case = TRUE)) {
        result[i] <- -2
      } else {
        result[i] <- -3  # Shouldn't happen but fallback
      }
      next
    }

    # Map substantive values to 6 categories
    if (val %in% c(1, 2)) {
      result[i] <- 1  # Employed
    } else if (val %in% c(3, 7)) {
      result[i] <- 2  # Unemployed
    } else if (val %in% c(4, 5, 10)) {
      result[i] <- 3  # Education
    } else if (val %in% c(4, 5, 6)) {
      result[i] <- 4  # Training
    } else if (val %in% c(6, 8, 9)) {
      result[i] <- 5  # Home/Family
    } else if (val %in% c(7, 11)) {
      result[i] <- 6  # Other/Retired
    } else {
      result[i] <- 6  # Other (catch-all)
    }
  }
  result
}

# Actually, I need to think about this more carefully.
# Let me create separate recoding functions for each wave's source variable
# since they have different categories.

# Wave 4 (Age 17): W4empsYP
# 1: Doing paid work >=30 hrs, 2: <30 hrs -> Employed
# 3: Unemployed/Looking for job -> Unemployed
# 4: Training course/scheme -> Training
# 5: Full-time education/school -> Education
# 6: Looking after family/household -> Home/Family
# 7: Retired -> Other
# 8: Sick/disabled -> Other
# 9: Other -> Other
recode_w4 <- function(x) {
  result <- rep(-3, length(x))  # Default: not asked
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      ref <- attr(x, "labels")
      if (!is.null(ref) && !is.na(x[i]) && as.character(x[i]) %in% names(ref)) {
        lbl <- as.character(ref[as.character(x[i])])
        if (grepl("Refused", lbl, ignore.case = TRUE)) result[i] <- -9
        else if (grepl("Insufficient", lbl, ignore.case = TRUE)) result[i] <- -8
        else if (grepl("Not applicable.*school", lbl, ignore.case = TRUE)) result[i] <- -3
        else if (grepl("Missing household", lbl, ignore.case = TRUE)) result[i] <- -2
        else result[i] <- -3
      } else {
        result[i] <- -3
      }
    } else if (x[i] > 0) {
      if (x[i] %in% c(1, 2)) result[i] <- 1  # Employed
      else if (x[i] == 3) result[i] <- 2  # Unemployed
      else if (x[i] == 4) result[i] <- 4  # Training
      else if (x[i] == 5) result[i] <- 3  # Education
      else if (x[i] == 6) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (7=Retired, 8=Sick, 9=Other)
    } else {
      # Handle negative codes
      if (x[i] == -92) result[i] <- -9
      else if (x[i] == -94) result[i] <- -8
      else if (x[i] == -91) result[i] <- -3
      else if (x[i] <= -999) result[i] <- -2
      else result[i] <- -3
    }
  }
  result
}

# Wave 5 (Age 18): W5mainactYP
# 1: Apprenticeship, 2: Part week employer/part week college -> Training/Employed+Education
# 3: Paid work -> Employed
# 4: Education -> Education
# 5: Training course/scheme -> Training
# 6: Entry to Employment scheme -> Training
# 7: Unemployed -> Unemployed
# 8: Looking after family/home -> Home/Family
# 9, 10, 11: Waiting -> Other (waiting for course/job/exams)
recode_w5 <- function(x) {
  result <- rep(-3, length(x))
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      result[i] <- -3
    } else if (x[i] > 0) {
      if (x[i] == 3) result[i] <- 1  # Employed
      else if (x[i] == 7) result[i] <- 2  # Unemployed
      else if (x[i] == 4) result[i] <- 3  # Education
      else if (x[i] %in% c(1, 2, 5, 6)) result[i] <- 4  # Training (incl. apprenticeship)
      else if (x[i] == 8) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (9, 10, 11 = waiting)
    } else {
      if (x[i] == -94) result[i] <- -8
      else result[i] <- -3
    }
  }
  result
}

# Wave 6 (Age 19): W6TCurrentAct
# 1: University, 2: Education -> Education
# 3: Paid work -> Employed
# 4: Training course/scheme -> Training
# 5: Apprenticeship -> Training
# 6: Waiting for course/job -> Other
# 7: Looking after family/home -> Home/Family
# 8: Unemployed -> Unemployed
# 9: Waiting for exam/job result -> Other
# 10: Part week employer/part week college -> Training/Education mix -> Training
# 11: Voluntary work -> Other (unpaid)
recode_w6 <- function(x) {
  result <- rep(-3, length(x))
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      result[i] <- -3
    } else if (x[i] > 0) {
      if (x[i] == 3) result[i] <- 1  # Employed
      else if (x[i] == 8) result[i] <- 2  # Unemployed
      else if (x[i] %in% c(1, 2)) result[i] <- 3  # Education
      else if (x[i] %in% c(4, 5, 10)) result[i] <- 4  # Training
      else if (x[i] == 7) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (6, 9, 11)
    } else {
      if (x[i] == -91) result[i] <- -8  # Unable to classify -> insufficient info
      else result[i] <- -3
    }
  }
  result
}

# Wave 7 (Age 20): W7TCurrentAct
# 1: University, 2: School/college -> Education
# 3: Paid work -> Employed
# 4: Training course/scheme -> Training
# 5: Apprenticeship -> Training
# 6: Waiting for course/job -> Other
# 7: Looking after home/family -> Home/Family
# 8: Unemployed -> Unemployed
# 9: Part time job + part time college -> Employed (has job)
# 10: Voluntary work -> Other
# 11: Gov employment programme -> Training
# 12: Travelling -> Other
# 13: Break from work/college -> Other
# 14: Ill or disabled -> Other
# 15: Not defined -> Other
recode_w7 <- function(x) {
  result <- rep(-3, length(x))
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      result[i] <- -3
    } else if (x[i] > 0) {
      if (x[i] %in% c(3, 9)) result[i] <- 1  # Employed (paid work, part time job)
      else if (x[i] == 8) result[i] <- 2  # Unemployed
      else if (x[i] %in% c(1, 2)) result[i] <- 3  # Education
      else if (x[i] %in% c(4, 5, 11)) result[i] <- 4  # Training
      else if (x[i] == 7) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (6, 10, 12, 13, 14, 15)
    } else {
      if (x[i] == -91) result[i] <- -3  # Not applicable
      else result[i] <- -3
    }
  }
  result
}

# Wave 8 (Age 25): W8DACTIVITYC (detailed 10-category)
# 1: Employee -> Employed
# 2: Self employed -> Employed
# 3: Unpaid/voluntary -> Other
# 4: Unemployed -> Unemployed
# 5: Education -> Education
# 6: Apprenticeship -> Training
# 7: Gov scheme -> Training
# 8: Sick/disabled -> Other
# 9: Looking after home/family -> Home/Family
# 10: Something else -> Other
recode_w8 <- function(x) {
  result <- rep(-3, length(x))
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      result[i] <- -3
    } else if (x[i] > 0) {
      if (x[i] %in% c(1, 2)) result[i] <- 1  # Employed
      else if (x[i] == 4) result[i] <- 2  # Unemployed
      else if (x[i] == 5) result[i] <- 3  # Education
      else if (x[i] %in% c(6, 7)) result[i] <- 4  # Training
      else if (x[i] == 9) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (3=voluntary, 8=sick, 10=other)
    } else {
      if (x[i] == -9) result[i] <- -9
      else if (x[i] == -8) result[i] <- -8
      else if (x[i] == -1) result[i] <- -3
      else result[i] <- -3
    }
  }
  result
}

# Wave 9 (Age 32): W9DACTIVITYC (same detailed 10-category as wave 8)
recode_w9 <- function(x) {
  result <- rep(-3, length(x))
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      result[i] <- -3
    } else if (x[i] > 0) {
      if (x[i] %in% c(1, 2)) result[i] <- 1  # Employed
      else if (x[i] == 4) result[i] <- 2  # Unemployed
      else if (x[i] == 5) result[i] <- 3  # Education
      else if (x[i] %in% c(6, 7)) result[i] <- 4  # Training
      else if (x[i] == 9) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (3=voluntary, 8=sick, 10=other)
    } else {
      if (x[i] == -9) result[i] <- -9
      else if (x[i] == -8) result[i] <- -8
      else if (x[i] == -1) result[i] <- -3
      else result[i] <- -3
    }
  }
  result
}

# Apply recoding
merged$ecoact17 <- recode_w4(merged$W4empsYP)
merged$ecoact18 <- recode_w5(merged$W5mainactYP)
merged$ecoact19 <- recode_w6(merged$W6TCurrentAct)
merged$ecoact20 <- recode_w7(merged$W7TCurrentAct)
merged$ecoact25 <- recode_w8(merged$W8DACTIVITYC)
merged$ecoact32 <- recode_w9(merged$W9DACTIVITYC)

# Create detailed adult variables for ages 25 and 32
# ecoactadu25: detailed version of W8DACTIVITYC
# ecoactadu32: detailed version of W9DACTIVITYC
merged$ecoactadu25 <- merged$W8DACTIVITYC
merged$ecoactadu32 <- merged$W9DACTIVITYC

# Convert raw missing codes to standard codes for detailed variables
for (col in c("ecoactadu25", "ecoactadu32")) {
  for (i in seq_along(merged[[col]])) {
    if (!is.na(merged[[col]][i]) && merged[[col]][i] < 0) {
      val <- merged[[col]][i]
      if (val == -9) merged[[col]][i] <- -9
      else if (val == -8) merged[[col]][i] <- -8
      else if (val == -1) merged[[col]][i] <- -3
      else merged[[col]][i] <- -3
    }
  }
}

# Set up factor labels for collapsed variables
ecoact_labels <- c(
  "1" = "Employed",
  "2" = "Unemployed",
  "3" = "Education",
  "4" = "Training",
  "5" = "Home/Family",
  "6" = "Other",
  "-9" = "Refusal",
  "-8" = "Don't know",
  "-7" = "Prefer not to say",
  "-3" = "Not asked",
  "-2" = "Not applicable",
  "-1" = "Item not applicable"
)

# Apply labelled factors to collapsed variables
for (var in c("ecoact17", "ecoact18", "ecoact19", "ecoact20", "ecoact25", "ecoact32")) {
  merged[[var]] <- haven::labelled(merged[[var]], labels = ecoact_labels)
}

# Apply labels to detailed adult variables
detailed_labels <- c(
  "1" = "Employee - in paid work",
  "2" = "Self employed",
  "3" = "In unpaid/voluntary work",
  "4" = "Unemployed",
  "5" = "Education: School/college/university",
  "6" = "Apprenticeship",
  "7" = "On gov't scheme for employment training",
  "8" = "Sick or disabled",
  "9" = "Looking after home or family",
  "10" = "Something else",
  "-9" = "Refused",
  "-8" = "Insufficient information",
  "-3" = "Not applicable"
)

merged$ecoactadu25 <- haven::labelled(merged$ecoactadu25, labels = detailed_labels)
merged$ecoactadu32 <- haven::labelled(merged$ecoactadu32, labels = detailed_labels)

# Select only ID and derived variables
output <- merged %>% select(NSID, ecoact17, ecoact18, ecoact19, ecoact20, ecoact25, ecoact32, ecoactadu25, ecoactadu32)

# Write output
write_csv(output, "data/output/cleaned_data.csv")

cat("Output written successfully\n")
cat("Output dimensions:", dim(output), "\n")
cat("Variables:", names(output), "\n")

# Summary of values
for (var in names(output)) {
  cat("\n", var, ":\n")
  print(summary(output[[var]]))
}

