# since they have different categories.

# Wave 4 (Age 17): W4empsYP
# 1: Doing paid work >=30 hrs, 2: <30 hrs -> Employed
# 3: Unemployed/Looking for job -> Unemployed
# 4: Training course/scheme -> Training
# 5: Full-time education/school -> Education
# 6: Looking after family/household -> Home/Family
# 7: Retired -> Other
# 8: Sick/disabled -> Other
# 9: Other -> Other
recode_w4 <- function(x) {
  result <- rep(-3, length(x))  # Default: not asked
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      ref <- attr(x, "labels")
      if (!is.null(ref) && !is.na(x[i]) && as.character(x[i]) %in% names(ref)) {
        lbl <- as.character(ref[as.character(x[i])])
        if (grepl("Refused", lbl, ignore.case = TRUE)) result[i] <- -9
        else if (grepl("Insufficient", lbl, ignore.case = TRUE)) result[i] <- -8
        else if (grepl("Not applicable.*school", lbl, ignore.case = TRUE)) result[i] <- -3
        else if (grepl("Missing household", lbl, ignore.case = TRUE)) result[i] <- -2
        else result[i] <- -3
      } else {
        result[i] <- -3
      }
    } else if (x[i] > 0) {
      if (x[i] %in% c(1, 2)) result[i] <- 1  # Employed
      else if (x[i] == 3) result[i] <- 2  # Unemployed
      else if (x[i] == 4) result[i] <- 4  # Training
      else if (x[i] == 5) result[i] <- 3  # Education
      else if (x[i] == 6) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (7=Retired, 8=Sick, 9=Other)
    } else {
      # Handle negative codes
      if (x[i] == -92) result[i] <- -9
      else if (x[i] == -94) result[i] <- -8
      else if (x[i] == -91) result[i] <- -3
      else if (x[i] <= -999) result[i] <- -2
      else result[i] <- -3
    }
  }
  result
}

# Wave 5 (Age 18): W5mainactYP
# 1: Apprenticeship, 2: Part week employer/part week college -> Training/Employed+Education
# 3: Paid work -> Employed
# 4: Education -> Education
# 5: Training course/scheme -> Training
# 6: Entry to Employment scheme -> Training
# 7: Unemployed -> Unemployed
# 8: Looking after family/home -> Home/Family
# 9, 10, 11: Waiting -> Other (waiting for course/job/exams)
recode_w5 <- function(x) {
  result <- rep(-3, length(x))
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      result[i] <- -3
    } else if (x[i] > 0) {
      if (x[i] == 3) result[i] <- 1  # Employed
      else if (x[i] == 7) result[i] <- 2  # Unemployed
      else if (x[i] == 4) result[i] <- 3  # Education
      else if (x[i] %in% c(1, 2, 5, 6)) result[i] <- 4  # Training (incl. apprenticeship)
      else if (x[i] == 8) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (9, 10, 11 = waiting)
    } else {
      if (x[i] == -94) result[i] <- -8
      else result[i] <- -3
    }
  }
  result
}

# Wave 6 (Age 19): W6TCurrentAct
# 1: University, 2: Education -> Education
# 3: Paid work -> Employed
# 4: Training course/scheme -> Training
# 5: Apprenticeship -> Training
# 6: Waiting for course/job -> Other
# 7: Looking after family/home -> Home/Family
# 8: Unemployed -> Unemployed
# 9: Waiting for exam/job result -> Other
# 10: Part week employer/part week college -> Training/Education mix -> Training
# 11: Voluntary work -> Other (unpaid)
recode_w6 <- function(x) {
  result <- rep(-3, length(x))
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      result[i] <- -3
    } else if (x[i] > 0) {
      if (x[i] == 3) result[i] <- 1  # Employed
      else if (x[i] == 8) result[i] <- 2  # Unemployed
      else if (x[i] %in% c(1, 2)) result[i] <- 3  # Education
      else if (x[i] %in% c(4, 5, 10)) result[i] <- 4  # Training
      else if (x[i] == 7) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (6, 9, 11)
    } else {
      if (x[i] == -91) result[i] <- -8  # Unable to classify -> insufficient info
      else result[i] <- -3
    }
  }
  result
}

# Wave 7 (Age 20): W7TCurrentAct
# 1: University, 2: School/college -> Education
# 3: Paid work -> Employed
# 4: Training course/scheme -> Training
# 5: Apprenticeship -> Training
# 6: Waiting for course/job -> Other
# 7: Looking after home/family -> Home/Family
# 8: Unemployed -> Unemployed
# 9: Part time job + part time college -> Employed (has job)
# 10: Voluntary work -> Other
# 11: Gov employment programme -> Training
# 12: Travelling -> Other
# 13: Break from work/college -> Other
# 14: Ill or disabled -> Other
# 15: Not defined -> Other
recode_w7 <- function(x) {
  result <- rep(-3, length(x))
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      result[i] <- -3
    } else if (x[i] > 0) {
