      else if (x[i] == 8) result[i] <- 2  # Unemployed
      else if (x[i] %in% c(1, 2)) result[i] <- 3  # Education
      else if (x[i] %in% c(4, 5, 11)) result[i] <- 4  # Training
      else if (x[i] == 7) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (6, 10, 12, 13, 14, 15)
    } else {
      if (x[i] == -91) result[i] <- -3  # Not applicable
      else result[i] <- -3
    }
  }
  result
}

# Wave 8 (Age 25): W8DACTIVITYC (detailed 10-category)
# 1: Employee -> Employed
