# Wave 4 (Age 17): W4empsYP
# 1: Doing paid work >=30 hrs, 2: <30 hrs -> Employed
# 3: Unemployed/Looking for job -> Unemployed
# 4: Training course/scheme -> Training
# 5: Full-time education/school -> Education
# 6: Looking after family/household -> Home/Family
# 7: Retired -> Other
# 8: Sick/disabled -> Other
# 9: Other -> Other
recode_w4 <- function(x) {
  result <- rep(-3, length(x))  # Default: not asked
  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      ref <- attr(x, "labels")
      if (!is.null(ref) && !is.na(x[i]) && as.character(x[i]) %in% names(ref)) {
        lbl <- as.character(ref[as.character(x[i])])
        if (grepl("Refused", lbl, ignore.case = TRUE)) result[i] <- -9
        else if (grepl("Insufficient", lbl, ignore.case = TRUE)) result[i] <- -8
        else if (grepl("Not applicable.*school", lbl, ignore.case = TRUE)) result[i] <- -3
        else if (grepl("Missing household", lbl, ignore.case = TRUE)) result[i] <- -2
        else result[i] <- -3
      } else {
        result[i] <- -3
      }
    } else if (x[i] > 0) {
      if (x[i] %in% c(1, 2)) result[i] <- 1  # Employed
      else if (x[i] == 3) result[i] <- 2  # Unemployed
      else if (x[i] == 4) result[i] <- 4  # Training
      else if (x[i] == 5) result[i] <- 3  # Education
      else if (x[i] == 6) result[i] <- 5  # Home/Family
      else result[i] <- 6  # Other (7=Retired, 8=Sick, 9=Other)
    } else {
      # Handle negative codes
      if (x[i] == -92) result[i] <- -9
      else if (x[i] == -94) result[i] <- -8
      else if (x[i] == -91) result[i] <- -3
      else if (x[i] <= -999) result[i] <- -2
      else result[i] <- -3
    }
  }
  result
}

