# Helper function to convert NAs to standard missing codes
convert_missing <- function(x, ref_var) {
  # Map user missing codes from ref_var to standard codes
  ref_vals <- attr(ref_var, "labels")
  if (is.null(ref_vals)) return(x)

  for (i in seq_along(x)) {
    if (is.na(x[i])) {
      # Find corresponding ref value and get its label
      ref_code <- ref_var[i]
      if (!is.na(ref_code)) {
        lbl <- as.character(ref_vals[as.character(ref_code)])
        if (!is.na(lbl)) {
          if (grepl("Refused", lbl, ignore.case = TRUE)) x[i] <- -9
          else if (grepl("Insufficient|Unable to classify", lbl, ignore.case = TRUE)) x[i] <- -8
          else if (grepl("Not asked|Not applicable|still at school", lbl, ignore.case = TRUE)) x[i] <- -1
          else if (grepl("Missing household|information lost", lbl, ignore.case = TRUE)) x[i] <- -2
          else x[i] <- -3
        } else {
          x[i] <- -3
        }
      } else {
        x[i] <- -3
      }
    }
  }
  x
}

# Recode function for 6-category collapsed ecoact
collapse_economic <- function(x, source_var) {
  # First convert missing values
  x <- convert_missing(x, source_var)

  # Source value labels for this variable
  src_labels <- attr(source_var, "labels")

  # Map values to 6 categories
  result <- x
  for (i in seq_along(x)) {
    if (is.na(x[i]) || x[i] < 0) {
      # Already handled by convert_missing, keep as is
      next
    }

    val <- x[i]
    # Check if this value is a user-missing code in source
    if (!is.null(src_labels) && as.character(val) %in% names(src_labels)) {
      lbl <- as.character(src_labels[as.character(val)])
      if (grepl("Refused", lbl, ignore.case = TRUE)) {
        result[i] <- -9
      } else if (grepl("Insufficient|Unable to classify", lbl, ignore.case = TRUE)) {
        result[i] <- -8
      } else if (grepl("Not asked|Not applicable|still at school", lbl, ignore.case = TRUE)) {
        result[i] <- -3
      } else if (grepl("Missing household|information lost", lbl, ignore.case = TRUE)) {
        result[i] <- -2
      } else {
        result[i] <- -3  # Shouldn't happen but fallback
      }
      next
    }

    # Map substantive values to 6 categories
    if (val %in% c(1, 2)) {
      result[i] <- 1  # Employed
    } else if (val %in% c(3, 7)) {
      result[i] <- 2  # Unemployed
    } else if (val %in% c(4, 5, 10)) {
      result[i] <- 3  # Education
    } else if (val %in% c(4, 5, 6)) {
      result[i] <- 4  # Training
    } else if (val %in% c(6, 8, 9)) {
      result[i] <- 5  # Home/Family
    } else if (val %in% c(7, 11)) {
      result[i] <- 6  # Other/Retired
    } else {
      result[i] <- 6  # Other (catch-all)
    }
  }
  result
}

